import React, { useState, useCallback } from 'react';
import { Header } from './components/Header';
import { ToneSelector } from './components/ToneSelector';
import { OutputDisplay } from './components/OutputDisplay';
import { humanizeContent } from './services/geminiService';
import { ToneType } from './types';
import { ArrowRightIcon, TrashIcon } from '@heroicons/react/24/outline';

// Icons
import { SparklesIcon } from '@heroicons/react/24/solid';

function App() {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');
  const [selectedTone, setSelectedTone] = useState<ToneType>(ToneType.STANDARD);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleHumanize = useCallback(async () => {
    if (!inputText.trim()) {
      setError("Please enter some text to humanize.");
      return;
    }

    setLoading(true);
    setError(null);
    setOutputText('');

    try {
      const result = await humanizeContent(inputText, selectedTone);
      setOutputText(result);
    } catch (err: any) {
      setError(err.message || "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [inputText, selectedTone]);

  const handleClear = () => {
    setInputText('');
    setOutputText('');
    setError(null);
  };

  // Calculate words
  const wordCount = inputText.trim() ? inputText.trim().split(/\s+/).length : 0;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Header />

      <main className="flex-grow max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">

        <div className="text-center mb-10">
          <h2 className="text-3xl md:text-4xl font-extrabold text-slate-900 mb-4">
            Transform Robot Text to <span className="text-indigo-600">Human Speech</span>
          </h2>
          <p className="text-lg text-slate-600 max-w-2xl mx-auto">
            Paste your AI-generated content (English, Bengali, etc.) and we'll refine it to sound natural, engaging, and authentic.
          </p>
        </div>

        <div className="bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
          <div className="p-6 md:p-8">

            {/* Tone Selection */}
            <div className="mb-6">
              <label className="block text-sm font-semibold text-slate-700 mb-2 uppercase tracking-wider">
                Select Tone
              </label>
              <ToneSelector 
                selectedTone={selectedTone} 
                onSelect={setSelectedTone} 
                disabled={loading}
              />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

              {/* INPUT SECTION */}
              <div className="flex flex-col h-full">
                <div className="flex justify-between items-center mb-2">
                  <label className="text-sm font-semibold text-slate-700 uppercase tracking-wider">
                    Input Text
                  </label>
                  <div className="flex items-center gap-3">
                    <span className="text-xs text-slate-400 font-medium">
                      {wordCount} words
                    </span>
                    {inputText && (
                      <button 
                        onClick={handleClear}
                        className="text-xs text-red-500 hover:text-red-700 flex items-center gap-1 transition-colors"
                        disabled={loading}
                      >
                        <TrashIcon className="h-3 w-3" /> Clear
                      </button>
                    )}
                  </div>
                </div>

                <div className="relative flex-grow">
                  <textarea
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    placeholder="Paste your text here..."
                    disabled={loading}
                    className="w-full h-64 md:h-96 p-4 rounded-xl border border-slate-200 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 resize-none transition-all outline-none text-slate-800 bg-slate-50 placeholder:text-slate-400 leading-relaxed shadow-sm"
                  />
                </div>
              </div>

              {/* ACTION & OUTPUT SECTION */}
              <div className="flex flex-col h-full relative">

                {/* Mobile Action Button (Hidden on large screens, styled differently) */}
                <div className="lg:hidden my-4 flex justify-center">
                   <button
                    onClick={handleHumanize}
                    disabled={loading || !inputText.trim()}
                    className="w-full py-3 bg-indigo-600 text-white rounded-xl font-semibold shadow-lg hover:bg-indigo-700 active:scale-95 transition-all disabled:opacity-50 disabled:pointer-events-none flex items-center justify-center gap-2"
                  >
                    {loading ? 'Processing...' : 'Humanize Text'} <ArrowRightIcon className="h-5 w-5" />
                  </button>
                </div>

                {/* Desktop Center Action (Absolute positioned arrow) */}
                <div className="hidden lg:flex absolute left-0 top-1/2 -translate-x-1/2 -translate-y-1/2 z-10">
                   <button
                    onClick={handleHumanize}
                    disabled={loading || !inputText.trim()}
                    className="h-12 w-12 bg-indigo-600 text-white rounded-full shadow-xl hover:bg-indigo-700 hover:scale-110 transition-all disabled:opacity-50 disabled:pointer-events-none flex items-center justify-center border-4 border-white"
                    title="Humanize Text"
                  >
                     {loading ? (
                       <SparklesIcon className="h-6 w-6 animate-pulse" />
                     ) : (
                       <ArrowRightIcon className="h-6 w-6" />
                     )}
                  </button>
                </div>

                <OutputDisplay 
                  content={outputText} 
                  isLoading={loading} 
                />
              </div>
            </div>

            {/* Bottom Action Bar (Desktop mainly) */}
            <div className="mt-8 flex justify-end lg:justify-center">
               <button
                  onClick={handleHumanize}
                  disabled={loading || !inputText.trim()}
                  className="hidden lg:flex py-3 px-8 bg-indigo-600 text-white rounded-xl font-bold text-lg shadow-lg hover:bg-indigo-700 hover:shadow-indigo-200 hover:-translate-y-0.5 transition-all disabled:opacity-50 disabled:cursor-not-allowed items-center gap-2"
                >
                  <SparklesIcon className="h-5 w-5" />
                  {loading ? 'Humanizing...' : 'Humanize Text'}
                </button>
            </div>

            {error && (
              <div className="mt-4 p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-sm text-center animate-fade-in">
                {error}
              </div>
            )}
          </div>
        </div>

        <footer className="mt-12 pb-8 flex flex-col items-center gap-4 text-sm text-slate-400">
          <p>© {new Date().getFullYear()} Any HumanizeAI.</p>
          <div className="flex items-center justify-center gap-6">
            <a 
              href="https://www.facebook.com/SoumenGraphicDesign" 
              target="_blank" 
              rel="noopener noreferrer"
              className="flex items-center gap-2 hover:text-indigo-600 transition-colors"
            >
               <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true">
                  <path fillRule="evenodd" d="M22 12c0-5.523-4.477-10-10-10S2 6.477 2 12c0 4.991 3.657 9.128 8.438 9.878v-6.987h-2.54V12h2.54V9.797c0-2.506 1.492-3.89 3.777-3.89 1.094 0 2.238.195 2.238.195v2.46h-1.26c-1.243 0-1.63.771-1.63 1.562V12h2.773l-.443 2.89h-2.33v6.988C18.343 21.128 22 16.991 22 12z" clipRule="evenodd" />
               </svg>
               <span className="hidden sm:inline">Facebook</span>
            </a>
            <a 
              href="https://www.instagram.com/soumengraphicdesign/" 
              target="_blank" 
              rel="noopener noreferrer"
              className="flex items-center gap-2 hover:text-pink-600 transition-colors"
            >
               <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true">
                  <path fillRule="evenodd" d="M12.315 2c2.43 0 2.784.013 3.808.06 1.064.049 1.791.218 2.427.465a4.902 4.902 0 011.772 1.153 4.902 4.902 0 011.153 1.772c.247.636.416 1.363.465 2.427.048 1.067.06 1.407.06 4.123v.08c0 2.643-.012 2.987-.06 4.043-.049 1.064-.218 1.791-.465 2.427a4.902 4.902 0 01-1.153 1.772 4.902 4.902 0 01-1.772 1.153c-.636.247-1.363.416-2.427.465-1.067.048-1.407.06-4.123.06h-.08c-2.643 0-2.987-.012-4.043-.06-1.064-.049-1.791-.218-2.427-.465a4.902 4.902 0 01-1.772-1.153 4.902 4.902 0 01-1.153-1.772c-.247-.636-.416-1.363-.465-2.427-.047-1.024-.06-1.379-.06-3.808v-.63c0-2.43.013-2.784.06-3.808.049-1.064.218-1.791.465-2.427a4.902 4.902 0 011.153-1.772A4.902 4.902 0 015.468 3.2c.636-.247 1.363-.416 2.427-.465C8.901 2.013 9.256 2 11.685 2h.63zm-.081 1.802h-.468c-2.456 0-2.784.011-3.807.058-.975.045-1.504.207-1.857.344-.467.182-.8.398-1.15.748-.35.35-.566.683-.748 1.15-.137.353-.3.882-.344 1.857-.047 1.023-.058 1.351-.058 3.807v.468c0 2.456.011 2.784.058 3.807.045.975.207 1.504.344 1.857.182.466.399.8.748 1.15.35.35.683.566 1.15.748.353.137.882.3 1.857.344 1.054.048 1.37.058 4.041.058h.08c2.597 0 2.917-.01 3.96-.058.976-.045 1.505-.207 1.858-.344.466-.182.8-.398 1.15-.748.35-.35.566-.683.748-1.15.137-.353.3-.882.344-1.857.048-1.055.058-1.37.058-4.041v-.08c0-2.597-.01-2.917-.058-3.96-.045-.976-.207-1.505-.344-1.858a3.097 3.097 0 00-.748-1.15 3.098 3.098 0 00-1.15-.748c-.353-.137-.882-.3-1.857-.344-1.023-.047-1.351-.058-3.807-.058zM12 6.865a5.135 5.135 0 110 10.27 5.135 5.135 0 010-10.27zm0 1.802a3.333 3.333 0 100 6.666 3.333 3.333 0 000-6.666zm5.338-3.205a1.2 1.2 0 110 2.4 1.2 1.2 0 010-2.4z" clipRule="evenodd" />
               </svg>
               <span className="hidden sm:inline">Instagram</span>
            </a>
          </div>
        </footer>
      </main>
    </div>
  );
}

