import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { ToneSelector } from './components/ToneSelector';
import { OutputDisplay } from './components/OutputDisplay';
import { Features } from './components/Features';
import { HowItWorks } from './components/HowItWorks';
import { FAQ } from './components/FAQ';
import { HistorySidebar } from './components/HistorySidebar';
import { AuthModal } from './components/AuthModal';
import { humanizeContent } from './services/geminiService';
import { authService } from './services/authService';
import { ToneType, HistoryItem, User } from './types';
import { ArrowRightIcon, TrashIcon } from '@heroicons/react/24/outline';

// Icons
import { SparklesIcon } from '@heroicons/react/24/solid';

function App() {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');
  const [selectedTone, setSelectedTone] = useState<ToneType>(ToneType.STANDARD);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Auth State
  const [user, setUser] = useState<User | null>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  // History State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  // Load User Session on Mount
  useEffect(() => {
    const currentUser = authService.getCurrentUser();
    if (currentUser) {
      setUser(currentUser);
    }
  }, []);

  // --- HISTORY PERSISTENCE LOGIC ---

  // Determine the storage key based on the current user
  const historyKey = `humanize_history_${user ? user.id : 'guest'}`;

  // Ref to track the previous key. This is crucial to prevent "saving" the 
  // old user's history to the new user's key immediately after switching.
  const prevKeyRef = useRef(historyKey);

  // 1. Load History: Runs when the user (and thus the key) changes
  useEffect(() => {
    const savedHistory = localStorage.getItem(historyKey);
    if (savedHistory) {
      try {
        setHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error("Failed to parse history", e);
        setHistory([]);
      }
    } else {
      setHistory([]);
    }
  }, [historyKey]);

  // 2. Auto-Save History: Runs whenever the history state changes
  useEffect(() => {
    // If the key has changed since the last effect run (meaning we just switched users),
    // we must abort saving. The 'history' state currently holds the OLD user's data
    // and we haven't finished loading the NEW user's data yet.
    if (prevKeyRef.current !== historyKey) {
      prevKeyRef.current = historyKey;
      return;
    }

    // If keys match, it is safe to save the current state to storage
    localStorage.setItem(historyKey, JSON.stringify(history));
  }, [history, historyKey]);

  // --- END PERSISTENCE LOGIC ---

  // Auth Handlers
  const handleLoginSuccess = (loggedInUser: User) => {
    setUser(loggedInUser);
  };

  const handleLogout = () => {
    authService.logout();
    setUser(null);
  };

  const addToHistory = (original: string, humanized: string, tone: ToneType) => {
    const newItem: HistoryItem = {
      id: Date.now().toString(),
      original,
      humanized,
      tone,
      timestamp: Date.now(),
    };
    setHistory(prev => [newItem, ...prev].slice(0, 50));
  };

  const handleRestoreHistory = (item: HistoryItem) => {
    setInputText(item.original);
    setOutputText(item.humanized);
    setSelectedTone(item.tone);
    setIsHistoryOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDeleteHistoryItem = (id: string) => {
    setHistory(prev => prev.filter(item => item.id !== id));
  };

  const handleClearHistory = () => {
    if (confirm('Are you sure you want to clear your entire history?')) {
      setHistory([]);
    }
  };

  const handleHumanize = useCallback(async () => {
    if (!inputText.trim()) {
      setError("Please enter some text to humanize.");
      return;
    }

    setLoading(true);
    setError(null);
    setOutputText('');

    try {
      const result = await humanizeContent(inputText, selectedTone);
      setOutputText(result);
      addToHistory(inputText, result, selectedTone);
    } catch (err: any) {
      setError(err.message || "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [inputText, selectedTone]);

  const handleClear = () => {
    setInputText('');
    setOutputText('');
    setError(null);
  };

  const wordCount = inputText.trim() ? inputText.trim().split(/\s+/).length : 0;

  return (
    <div className="min-h-screen relative flex flex-col font-sans text-slate-800 overflow-x-hidden bg-[#f8fafc]">

      {/* Animated Background Blobs */}
      <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
        <div className="bg-blob bg-green-300 w-96 h-96 rounded-full top-0 left-0 -translate-x-1/2 -translate-y-1/2 opacity-30 mix-blend-multiply blur-3xl animate-blob"></div>
        <div className="bg-blob bg-slate-300 w-96 h-96 rounded-full top-0 right-0 translate-x-1/3 -translate-y-1/3 opacity-40 mix-blend-multiply blur-3xl animate-blob animation-delay-2000"></div>
        <div className="bg-blob bg-emerald-200 w-80 h-80 rounded-full bottom-0 left-20 translate-y-1/3 opacity-30 mix-blend-multiply blur-3xl animate-blob animation-delay-4000"></div>
      </div>

      <Header 
        onHistoryClick={() => setIsHistoryOpen(true)} 
        onLoginClick={() => setIsAuthModalOpen(true)}
        onLogoutClick={handleLogout}
        user={user}
      />

      <HistorySidebar 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        history={history}
        onRestore={handleRestoreHistory}
        onDelete={handleDeleteHistoryItem}
        onClearAll={handleClearHistory}
        user={user}
        onLoginClick={() => {
          setIsHistoryOpen(false);
          setIsAuthModalOpen(true);
        }}
      />

      <AuthModal 
        isOpen={isAuthModalOpen}
        onClose={() => setIsAuthModalOpen(false)}
        onLoginSuccess={handleLoginSuccess}
      />

      {/* HERO SECTION */}
      <div className="relative z-10 pb-12 md:pb-20 pt-8 md:pt-12">
        <main className="max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8">

          <div className="text-center mb-10 md:mb-12 animate-fade-in-up">
            <div className="inline-block mb-4 px-4 py-1.5 bg-white/60 backdrop-blur-sm text-green-700 rounded-full text-sm font-semibold tracking-wide border border-green-100 shadow-sm">
              ✨ Best AI Text Humanizer
            </div>
            <h2 className="text-4xl md:text-6xl font-extrabold text-slate-900 mb-6 tracking-tight leading-tight">
              Transform Robot Text to <br className="hidden md:block" />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-green-500 to-emerald-600">
                Human Speech
              </span>
            </h2>
            <p className="text-lg md:text-xl text-slate-600 max-w-2xl mx-auto leading-relaxed">
              Paste your AI-generated content (English, Bengali, etc.) and we'll refine it to sound natural, engaging, and authentic.
            </p>
          </div>

          {/* GLASS CARD */}
          <div className="glass-panel rounded-3xl p-6 md:p-10 animate-fade-in-up border-green-100/50" style={{animationDelay: '0.1s'}}>

              {/* Tone Selection */}
              <div className="mb-8">
                <label className="block text-xs font-bold text-slate-500 mb-3 uppercase tracking-wider ml-1">
                  Choose a Tone
                </label>
                <ToneSelector 
                  selectedTone={selectedTone} 
                  onSelect={setSelectedTone} 
                  disabled={loading}
                />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-12 relative">

                {/* INPUT SECTION */}
                <div className="flex flex-col h-full">
                  <div className="flex justify-between items-center mb-3">
                    <label className="text-sm font-semibold text-slate-700 flex items-center gap-2">
                      Input Text
                    </label>
                    <div className="flex items-center gap-3">
                      <span className="px-2 py-0.5 bg-white/50 rounded text-xs text-slate-500 font-medium border border-white/50">
                        {wordCount} words
                      </span>
                      {inputText && (
                        <button 
                          onClick={handleClear}
                          className="text-xs text-red-500 hover:text-red-700 hover:bg-red-50/50 px-2 py-0.5 rounded transition-colors flex items-center gap-1"
                          disabled={loading}
                        >
                          <TrashIcon className="h-3 w-3" /> Clear
                        </button>
                      )}
                    </div>
                  </div>

                  <div className="relative flex-grow group">
                    <textarea
                      value={inputText}
                      onChange={(e) => setInputText(e.target.value)}
                      placeholder="Paste your text here... (e.g. 'The quick brown fox...')"
                      disabled={loading}
                      className="w-full h-80 md:h-96 p-6 rounded-2xl glass-input resize-none outline-none text-slate-800 placeholder:text-slate-400/70 leading-relaxed text-lg focus:border-green-400 focus:ring-green-200"
                    />
                  </div>
                </div>

                {/* ACTION & OUTPUT SECTION */}
                <div className="flex flex-col h-full relative">

                  {/* Mobile Action Button */}
                  <div className="lg:hidden my-6 flex justify-center">
                     <button
                      onClick={handleHumanize}
                      disabled={loading || !inputText.trim()}
                      className="w-full py-4 bg-green-500 text-white rounded-xl font-bold shadow-lg shadow-green-500/30 hover:bg-green-600 active:scale-95 transition-all disabled:opacity-50 disabled:pointer-events-none flex items-center justify-center gap-2 text-lg"
                    >
                      {loading ? 'Processing...' : 'Humanize Text'} <ArrowRightIcon className="h-5 w-5" />
                    </button>
                  </div>

                  {/* Desktop Center Action (Absolute) */}
                  <div className="hidden lg:flex absolute -left-6 top-1/2 -translate-y-1/2 z-20">
                     <button
                      onClick={handleHumanize}
                      disabled={loading || !inputText.trim()}
                      className="h-16 w-16 bg-gradient-to-br from-green-500 to-emerald-600 text-white rounded-full shadow-xl shadow-green-500/40 hover:scale-110 hover:shadow-2xl transition-all disabled:opacity-50 disabled:pointer-events-none flex items-center justify-center border-4 border-white/80"
