  const historyKey = `humanize_history_${user ? user.id : 'guest'}`;

  // Ref to track the previous key. This is crucial to prevent "saving" the 
  // old user's history to the new user's key immediately after switching.
  const prevKeyRef = useRef(historyKey);

  // 1. Load History: Runs when the user (and thus the key) changes
  useEffect(() => {
    const savedHistory = localStorage.getItem(historyKey);
    if (savedHistory) {
      try {
