import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { ToneSelector } from './components/ToneSelector';
import { OutputDisplay } from './components/OutputDisplay';
import { ModeSelector } from './components/ModeSelector';
import { ScriptOptions } from './components/ScriptOptions';
import { Features } from './components/Features';
import { HowItWorks } from './components/HowItWorks';
import { FAQ } from './components/FAQ';
import { HistorySidebar } from './components/HistorySidebar';
import { AuthModal } from './components/AuthModal';
import { humanizeContent, generateScript } from './services/geminiService';
import { authService } from './services/authService';
import { ToneType, HistoryItem, User, AppMode, ScriptFormat } from './types';
import { 
  ArrowRightIcon, 
  TrashIcon, 
  ArrowUturnLeftIcon, 
  ArrowUturnRightIcon,
  VideoCameraIcon 
} from '@heroicons/react/24/outline';

// Icons
import { SparklesIcon } from '@heroicons/react/24/solid';

function App() {
  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (localStorage.getItem('theme') === 'dark') return true;
    if (localStorage.getItem('theme') === 'light') return false;
    return window.matchMedia('(prefers-color-scheme: dark)').matches;
  });

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  const toggleTheme = () => setDarkMode(!darkMode);

  // App State
  const [mode, setMode] = useState<AppMode>(AppMode.HUMANIZE);
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Humanize Options
  const [selectedTone, setSelectedTone] = useState<ToneType>(ToneType.STANDARD);

  // Script Options
  const [scriptFormat, setScriptFormat] = useState<ScriptFormat>(ScriptFormat.YOUTUBE_VIDEO);
  const [scriptLanguage, setScriptLanguage] = useState('English');

  // Auth State
  const [user, setUser] = useState<User | null>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  // History State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  // Undo/Redo State (Only for Humanize Mode input)
  const [undoStack, setUndoStack] = useState<string[]>(['']);
  const [undoIndex, setUndoIndex] = useState(0);
  const undoTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Load User Session on Mount
  useEffect(() => {
    const currentUser = authService.getCurrentUser();
    if (currentUser) {
      setUser(currentUser);
    }
  }, []);

  // --- HISTORY PERSISTENCE LOGIC ---
  const historyKey = `humanize_history_${user ? user.id : 'guest'}`;
  const prevKeyRef = useRef(historyKey);

  useEffect(() => {
    const savedHistory = localStorage.getItem(historyKey);
    if (savedHistory) {
      try {
        setHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error("Failed to parse history", e);
        setHistory([]);
      }
    } else {
      setHistory([]);
    }
  }, [historyKey]);

  useEffect(() => {
    if (prevKeyRef.current !== historyKey) {
      prevKeyRef.current = historyKey;
      return;
    }
    localStorage.setItem(historyKey, JSON.stringify(history));
  }, [history, historyKey]);

  // --- UNDO/REDO LOGIC (Humanize Mode Only) ---
  const pushToUndoStack = (text: string) => {
    setUndoStack(prev => {
      const newStack = prev.slice(0, undoIndex + 1);
      if (newStack[newStack.length - 1] !== text) {
        const updatedStack = [...newStack, text];
        setUndoIndex(updatedStack.length - 1);
        return updatedStack;
      }
      return prev;
    });
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement | HTMLInputElement>) => {
    const newText = e.target.value;
    setInputText(newText);

    // Only perform undo/redo logic if in humanize mode and input is textarea
    if (mode === AppMode.HUMANIZE) {
      if (undoTimeoutRef.current) {
        clearTimeout(undoTimeoutRef.current);
      }
      undoTimeoutRef.current = setTimeout(() => {
        setUndoStack(prev => {
          const sliced = prev.slice(0, undoIndex + 1);
          if (sliced[sliced.length - 1] !== newText) {
            const updatedStack = [...sliced, newText];
            setUndoIndex(updatedStack.length - 1);
            return updatedStack;
          }
          return prev;
        });
      }, 700);
    }
  };

  const handleUndo = () => {
    if (undoIndex > 0) {
      const newIndex = undoIndex - 1;
      setUndoIndex(newIndex);
      setInputText(undoStack[newIndex]);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    }
  };

  const handleRedo = () => {
    if (undoIndex < undoStack.length - 1) {
      const newIndex = undoIndex + 1;
      setUndoIndex(newIndex);
      setInputText(undoStack[newIndex]);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    }
  };

  // --- APP LOGIC ---

  const handleLoginSuccess = (loggedInUser: User) => {
    setUser(loggedInUser);
  };

  const handleLogout = () => {
    if (history.length >= 0) {
        localStorage.setItem(historyKey, JSON.stringify(history));
    }
    authService.logout();
    setUser(null);
  };

  const addToHistory = (original: string, humanized: string, typeLabel: string) => {
    const newItem: HistoryItem = {
      id: Date.now().toString(),
      original,
      humanized,
      tone: typeLabel, // Used for Tone or Script Format
      mode: mode,
      timestamp: Date.now(),
    };
    setHistory(prev => [newItem, ...prev].slice(0, 50));
  };

  const handleRestoreHistory = (item: HistoryItem) => {
    // Switch mode based on item history
    if (item.mode) {
      setMode(item.mode);
    } else {
      // Backward compatibility: try to guess or default to Humanize
      setMode(AppMode.HUMANIZE);
    }

    setInputText(item.original);
    setOutputText(item.humanized);

    // Set Tone or Format based on what we stored
    if (Object.values(ToneType).includes(item.tone as ToneType)) {
       setSelectedTone(item.tone as ToneType);
    } else if (Object.values(ScriptFormat).includes(item.tone as ScriptFormat)) {
       setScriptFormat(item.tone as ScriptFormat);
    }

    if (item.mode === AppMode.HUMANIZE) {
       pushToUndoStack(item.original);
    }

    setIsHistoryOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDeleteHistoryItem = (id: string) => {
    setHistory(prev => prev.filter(item => item.id !== id));
  };

  const handleClearHistory = () => {
    if (confirm('Are you sure you want to clear your entire history?')) {
      setHistory([]);
    }
  };

  const handleProcess = useCallback(async () => {
    if (!inputText.trim()) {
      setError(mode === AppMode.HUMANIZE ? "Please enter some text." : "Please enter a topic.");
      return;
    }

    setLoading(true);
    setError(null);
    setOutputText('');

    try {
      let result = '';
      let label = '';

      if (mode === AppMode.HUMANIZE) {
        result = await humanizeContent(inputText, selectedTone);
        label = selectedTone;
      } else {
        // Now passing selectedTone to generateScript
        result = await generateScript(inputText, scriptFormat, scriptLanguage, selectedTone);
        label = scriptFormat;
      }

      setOutputText(result);
      addToHistory(inputText, result, label);
    } catch (err: any) {
      setError(err.message || "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [inputText, mode, selectedTone, scriptFormat, scriptLanguage]);

  const handleClear = () => {
    if (inputText) {
      setInputText('');
      if (mode === AppMode.HUMANIZE) pushToUndoStack('');
      setOutputText('');
      setError(null);
    }
  };

