                    >
                      {loading ? 'Processing...' : (mode === AppMode.HUMANIZE ? 'Humanize Text' : 'Generate Script')} <ArrowRightIcon className="h-5 w-5" />
                    </button>
                  </div>

                  {/* Desktop Center Action (Absolute) */}
                  <div className="hidden lg:flex absolute -left-6 top-1/2 -translate-y-1/2 z-20">
