        label = scriptFormat;
      }

      setOutputText(result);
      addToHistory(inputText, result, label);
    } catch (err: any) {
      setError(err.message || "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }, [inputText, mode, selectedTone, scriptFormat, scriptLanguage, scriptStyle]);

  const handleClear = () => {
    if (inputText) {
      setInputText('');
      if (mode === AppMode.HUMANIZE) pushToUndoStack('');
      setOutputText('');
      setError(null);
    }
