```typescript
import { User } from '../types';

const USERS_KEY = 'humanize_users_db';
const SESSION_KEY = 'humanize_session_user';

// Simulated delay for realism
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Helper to check if string is likely a mobile number (digits only, 10-15 chars)
const isMobileNumber = (input: string) => {
  const mobileRegex = /^[0-9]{10,15}$/;
  return mobileRegex.test(input.replace(/\D/g, ''));
};

export const authService = {
  // Simulate sending an OTP
  async sendOtp(identifier: string): Promise<string> {
    await delay(1500); // Simulate network delay
    // Generate a random 6-digit OTP
    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    return otp;
  },

  async login(identifier: string): Promise<User> {
    await delay(500);

    const usersRaw = localStorage.getItem(USERS_KEY);
    const users = usersRaw ? JSON.parse(usersRaw) : [];

    // Find user by Email OR Mobile
    const user = users.find((u: any) => 
      u.email === identifier || u.mobile === identifier
    );

    if (!user) {
      throw new Error('User not found. Please sign up first.');
    }

    // Persist session (store entire user object sans sensitive data if any)
    localStorage.setItem(SESSION_KEY, JSON.stringify(user));
    return user;
  },

  async signup(name: string, identifier: string): Promise<User> {
    await delay(500);

    const usersRaw = localStorage.getItem(USERS_KEY);
    const users = usersRaw ? JSON.parse(usersRaw) : [];

    const isMobile = isMobileNumber(identifier);

    // Check for duplicates
    const exists = users.some((u: any) => 
      (u.email && u.email === identifier) || (u.mobile && u.mobile === identifier)
    );

    if (exists) {
      throw new Error(`User with this ${isMobile ? 'mobile number' : 'email'} already exists. Please log in.`);
    }

    const newUser = {
      id: Date.now().toString(),
      name,
      email: isMobile ? undefined : identifier,
      mobile: isMobile ? identifier : undefined,
      createdAt: Date.now()
    };

    users.push(newUser);
    localStorage.setItem(USERS_KEY, JSON.stringify(users));

    localStorage.setItem(SESSION_KEY, JSON.stringify(newUser));
    return newUser;
  },

  logout(): void {
    localStorage.removeItem(SESSION_KEY);
  },

  getCurrentUser(): User | null {
    const session = localStorage.getItem(SESSION_KEY);
    return session ? JSON.parse(session) : null;
  }
};
