import React, { useState, useEffect } from 'react';
import { XMarkIcon, UserIcon, IdentificationIcon, ChatBubbleLeftEllipsisIcon, ArrowPathIcon } from '@heroicons/react/24/outline';
import { authService } from '../services/authService';
import { User } from '../types';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLoginSuccess: (user: User) => void;
}

export const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, onLoginSuccess }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [step, setStep] = useState<1 | 2>(1); // Step 1: Details, Step 2: OTP
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form Data
  const [name, setName] = useState('');
  const [identifier, setIdentifier] = useState(''); // Email or Mobile
  const [otpInput, setOtpInput] = useState('');

  // OTP Logic
  const [generatedOtp, setGeneratedOtp] = useState<string | null>(null);
  const [timer, setTimer] = useState(0);

  useEffect(() => {
    let interval: ReturnType<typeof setTimeout>;
    if (timer > 0) {
      interval = setInterval(() => setTimer((prev) => prev - 1), 1000);
    }
    return () => clearInterval(interval);
  }, [timer]);

  // Reset state when modal opens/closes
  useEffect(() => {
    if (isOpen) {
      setStep(1);
      setError(null);
      setOtpInput('');
      setGeneratedOtp(null);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!identifier) {
      setError("Please enter your email or mobile number.");
      return;
    }
    if (!isLogin && !name) {
      setError("Please enter your name.");
      return;
    }

    setIsLoading(true);
    try {
      // If logging in, check if user exists first (optional, but good UX)
      if (isLogin) {
        // In a real app, we might check existence here. 
        // For this demo, we'll let sendOtp happen, then fail at verify step if logic dictates, 
        // OR we can assume if they have the OTP for that identifier, they own it.
        // However, our authService.login requires the user to be in the DB.
        // So technically we should verify existence before sending OTP if strict, 
        // but standard flow often sends OTP anyway to prevent enumeration attacks.
        // We will proceed to send OTP.
      }

      const code = await authService.sendOtp(identifier);
      setGeneratedOtp(code);

      // SIMULATION: Show OTP in alert
      alert(`Your OTP code is: ${code}`);

      setStep(2);
      setTimer(30); // 30 seconds cooldown
    } catch (err: any) {
      setError(err.message || "Failed to send OTP.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (otpInput !== generatedOtp) {
      setError("Invalid OTP code. Please try again.");
      return;
    }

    setIsLoading(true);
    try {
      let user;
      if (isLogin) {
        user = await authService.login(identifier);
      } else {
        user = await authService.signup(name, identifier);
      }
      onLoginSuccess(user);
      onClose();
    } catch (err: any) {
      setError(err.message || "Authentication failed.");
      // If user not found during login, maybe suggest signup?
      if (isLogin && err.message.includes('not found')) {
        setTimeout(() => {
           if(confirm("User not found. Would you like to create an account?")) {
             setIsLogin(false);
             setStep(1);
             setGeneratedOtp(null);
             setOtpInput('');
             setError(null);
           }
        }, 100);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleResendOtp = async () => {
    if (timer > 0) return;
    setIsLoading(true);
    try {
      const code = await authService.sendOtp(identifier);
      setGeneratedOtp(code);
      alert(`Your new OTP code is: ${code}`);
      setTimer(30);
    } catch (err: any) {
      setError("Failed to resend OTP.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
      <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-scale-in relative border border-green-500/20 dark:border-green-500/30">
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-1 rounded-full hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors"
        >
          <XMarkIcon className="h-6 w-6" />
        </button>

        <div className="p-8">
          <div className="text-center mb-8">
            <h2 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">
              {step === 1 ? (isLogin ? 'Welcome Back' : 'Create Account') : 'Verify OTP'}
            </h2>
            <p className="text-slate-500 dark:text-slate-400 text-sm">
              {step === 1 
                ? 'Secure login with One-Time Password' 
                : `Enter the code sent to ${identifier}`
              }
            </p>
          </div>

          {error && (
            <div className="mb-6 p-3 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/30 text-red-600 dark:text-red-400 text-sm rounded-lg text-center animate-pulse">
              {error}
            </div>
          )}

          {step === 1 ? (
            <form onSubmit={handleSendOtp} className="space-y-4">
              {!isLogin && (
                <div className="relative">
                  <UserIcon className="h-5 w-5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                  <input
                    type="text"
                    placeholder="Full Name"
                    className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white focus:border-green-500 dark:focus:border-green-500 focus:ring-2 focus:ring-green-200 dark:focus:ring-green-900 outline-none transition-all"
                    value={name}
                    onChange={e => setName(e.target.value)}
                    required={!isLogin}
                  />
                </div>
              )}

              <div className="relative">
                <IdentificationIcon className="h-5 w-5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text" 
                  placeholder="Email or Mobile Number"
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white focus:border-green-500 dark:focus:border-green-500 focus:ring-2 focus:ring-green-200 dark:focus:ring-green-900 outline-none transition-all"
                  value={identifier}
                  onChange={e => setIdentifier(e.target.value)}
                  required
                />
              </div>

              <button
                type="submit"
                disabled={isLoading}
                className="w-full py-3 bg-green-500 text-white rounded-xl font-bold shadow-lg shadow-green-200 dark:shadow-green-900/40 hover:bg-green-600 hover:-translate-y-0.5 transition-all disabled:opacity-70 disabled:cursor-not-allowed mt-2 flex items-center justify-center gap-2"
              >
                {isLoading ? 'Sending OTP...' : 'Get OTP'} <ChatBubbleLeftEllipsisIcon className="h-5 w-5" />
              </button>
            </form>
          ) : (
            <form onSubmit={handleVerifyOtp} className="space-y-6">
              <div>
                <input
                  type="text"
                  placeholder="Enter 6-digit Code"
                  maxLength={6}
                  className="w-full text-center text-2xl tracking-[0.5em] font-bold py-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white focus:border-green-500 dark:focus:border-green-500 focus:ring-2 focus:ring-green-200 dark:focus:ring-green-900 outline-none transition-all uppercase"
                  value={otpInput}
                  onChange={e => setOtpInput(e.target.value.replace(/[^0-9]/g, ''))}
                  autoFocus
                />
              </div>

              <button
                type="submit"
                disabled={isLoading || otpInput.length !== 6}
                className="w-full py-3 bg-green-500 text-white rounded-xl font-bold shadow-lg shadow-green-200 dark:shadow-green-900/40 hover:bg-green-600 hover:-translate-y-0.5 transition-all disabled:opacity-70 disabled:cursor-not-allowed"
              >
                {isLoading ? 'Verifying...' : 'Verify & Continue'}
              </button>

              <div className="flex justify-between items-center text-sm">
                <button 
                  type="button"
                  onClick={() => setStep(1)}
                  className="text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                >
                  Change Number
                </button>

                <button
                  type="button"
                  onClick={handleResendOtp}
