          {/* OTP DISPLAY BANNER (FREE MODE) */}
          {step === 2 && generatedOtp && (
            <div className="mb-6 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-900/30 rounded-xl flex flex-col items-center gap-2 animate-fade-in-up">
              <span className="text-xs font-bold text-blue-600 dark:text-blue-400 uppercase tracking-wider">
