                <button 
                  onClick={() => {
                    navigator.clipboard.writeText(generatedOtp);
                    setOtpInput(generatedOtp); // Auto-fill for convenience
                  }}
                  className="p-1.5 bg-white dark:bg-slate-800 rounded-lg text-slate-500 hover:text-blue-600 shadow-sm transition-colors"
                  title="Copy Code"
                >
                  <ClipboardDocumentCheckIcon className="h-5 w-5" />
