                          disabled={loading}
                        >
                          <TrashIcon className="h-3 w-3" /> Clear
                        </button>
                      )}
                    </div>
                  </div>

                  <div className="relative flex-grow group">
                    {mode === AppMode.HUMANIZE ? (
                      <textarea
                        value={inputText}
                        onChange={handleInputChange}
