                      title={mode === AppMode.HUMANIZE ? "Humanize Text" : mode === AppMode.SCRIPT ? "Generate Script" : mode === AppMode.SEO_YT ? "Generate Metadata" : "Generate Captions"}
                    >
                       {loading ? (
                         <SparklesIcon className="h-8 w-8 animate-pulse" />
