                         mode === AppMode.HUMANIZE ? <ArrowRightIcon className="h-8 w-8" /> : mode === AppMode.SCRIPT ? <VideoCameraIcon className="h-8 w-8" /> : mode === AppMode.SEO_YT ? <TagIcon className="h-8 w-8" /> : <DevicePhoneMobileIcon className="h-8 w-8" />
