                    {loading ? 'Processing...' : (mode === AppMode.HUMANIZE ? 'Humanize Text' : mode === AppMode.SCRIPT ? 'Generate Script' : mode === AppMode.SEO_YT ? 'Generate Metadata' : 'Generate Captions')}
