          <div className="glass-panel rounded-3xl p-6 md:p-10 animate-fade-in-up border-green-100/50 dark:border-white/5" style={{animationDelay: '0.1s'}}>

              {/* Mode Specific Controls */}
              {mode === AppMode.HUMANIZE ? (
