              )}
              {mode === AppMode.SCRIPT && (
                <>
                  Generate Viral <br className="hidden md:block" />
                  <span className="text-transparent bg-clip-text bg-gradient-to-r from-green-500 to-emerald-600 dark:from-green-400 dark:to-emerald-500">
                    Video Scripts
                  </span>
                </>
