import { GoogleGenAI } from "@google/genai";
import { ToneType, ScriptFormat, ScriptStyle, CaptionTone, VideoCategory, Platform } from "../types";

const apiKey = process.env.API_KEY;
if (!apiKey) {
  console.error("API_KEY is missing from the environment variables.");
}

const ai = new GoogleGenAI({ apiKey: apiKey || 'DUMMY_KEY_FOR_BUILD' });

const modelId = "gemini-2.5-flash";

export const humanizeContent = async (text: string, tone: ToneType): Promise<string> => {
  if (!text.trim()) return "";

  const systemInstruction = `
    You are an expert writer and editor specializing in "humanizing" text. 
    Your goal is to take input text (which may be AI-generated or stiff) and rewrite it to sound natural, fluid, and human.

    Rules:
    1. Detect the language of the input text (e.g., English, Bengali, Spanish) and output in the SAME language.
    2. Remove robotic transitions (e.g., "In conclusion", "Furthermore", "Delving into").
    3. Vary sentence length and structure.
    4. Use idioms or natural phrasing appropriate for the requested tone.
    5. Keep the core meaning exactly the same, just change the delivery.
    6. Do not add conversational filler like "Here is your text" at the start. Just provide the rewritten text.
  `;

  const prompt = `
    Rewrite the following text to be more "${tone}" in tone. 
    Make it sound like a real human wrote it.

    Input Text:
    """
    ${text}
    """
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.8,
      },
    });

    return response.text || "Failed to generate text.";
  } catch (error: any) {
    console.error("Error in humanizeContent:", error);
    throw new Error("Failed to connect to Gemini API. Please check your connection or API key.");
  }
};

export const generateScript = async (topic: string, format: ScriptFormat, language: string, style: ScriptStyle): Promise<string> => {
  if (!topic.trim()) return "";

  const systemInstruction = `
    You are an advanced Script Writer AI specializing in creating high-retention video scripts for various platforms.
    Your goal is to generate structured, engaging content strictly following the user's parameters.

    OUTPUT FORMAT:
    The output MUST be a well-structured script containing:
    A. Script Intro (Strong hook, 1–2 lines)
    B. Main Script Body (well-structured & engaging)
    C. Ending CTA (Call to Action)
    D. Viral Caption (Optimized for the platform and language)
    E. Short Description (SEO-optimized summary)
    F. SEO & Trending Hashtags (30 optimized tags)
    G. Relatable Topic Tags (20 relevant tags)

    RULES:
    - Always follow the exact selected parameters (Format, Language, Style).
    - Maintain a professional yet engaging structure.
    - Ensure the script matches the requested platform format (e.g., TikTok/Reels needs to be fast-paced, YouTube can be longer).
    - Do NOT include conversational filler before the script. Start directly with the Intro.
  `;

  const prompt = `
    Generate a professional video script based on the following parameters:

    1. Topic: "${topic}"
    2. Content Type: ${format}
    3. Target Language: ${language}
    4. Script Style: ${style}

    Requirement: Create a viral, high-quality script that fits this specific style and platform format.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.9,
      },
    });

    return response.text || "Failed to generate script.";
  } catch (error: any) {
    console.error("Error in generateScript:", error);
    throw new Error("Failed to connect to Gemini API. Please check your connection or API key.");
  }
};

export const generateSeoMetadata = async (topic: string, language: string): Promise<string> => {
