import React, { useRef } from 'react';
import { PhotoIcon, XMarkIcon } from '@heroicons/react/24/outline';

interface ThumbnailOptionsProps {
  aspectRatio: string;
  setAspectRatio: (ratio: string) => void;
  image: string | null;
  setImage: (image: string | null) => void;
  disabled: boolean;
}

export const ThumbnailOptions: React.FC<ThumbnailOptionsProps> = ({
  aspectRatio,
  setAspectRatio,
  image,
  setImage,
  disabled
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const ratios = ['16:9', '9:16', '1:1', '4:5'];

  return (
    <div className="space-y-6 animate-fade-in mb-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Aspect Ratio */}
        <div className="space-y-2">
          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider ml-1">
            Aspect Ratio
          </label>
          <div className="flex flex-wrap gap-2">
            {ratios.map((ratio) => (
              <button
                key={ratio}
                onClick={() => setAspectRatio(ratio)}
                disabled={disabled}
                className={`
                  px-4 py-2 rounded-xl text-sm font-medium transition-all
                  ${aspectRatio === ratio
                    ? 'bg-green-500 text-white shadow-lg shadow-green-500/30'
                    : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700'
                  }
                  ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
                `}
              >
                {ratio}
              </button>
            ))}
          </div>
        </div>

        {/* Image Upload */}
        <div className="space-y-2">
          <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider ml-1">
            Reference Image (Optional)
          </label>

          {!image ? (
            <div 
              onClick={() => !disabled && fileInputRef.current?.click()}
              className={`
                border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-xl p-4
                flex flex-col items-center justify-center text-center cursor-pointer
                hover:border-green-500 dark:hover:border-green-500 transition-colors
                bg-white/50 dark:bg-slate-800/50 h-24
                ${disabled ? 'opacity-50 cursor-not-allowed' : ''}
              `}
            >
              <PhotoIcon className="h-6 w-6 text-slate-400 mb-1" />
              <span className="text-xs text-slate-500">Upload Image for Analysis</span>
            </div>
          ) : (
            <div className="relative h-24 w-full rounded-xl overflow-hidden border border-slate-200 dark:border-slate-700 group">
              <img src={image} alt="Uploaded" className="w-full h-full object-cover" />
              <div className="absolute inset-0 bg-black/20 group-hover:bg-black/40 transition-colors" />
              <button
                onClick={() => {
                  setImage(null);
                  if (fileInputRef.current) fileInputRef.current.value = '';
                }}
                className="absolute top-2 right-2 p-1.5 bg-black/50 hover:bg-red-500 text-white rounded-full transition-colors backdrop-blur-sm"
              >
                <XMarkIcon className="h-4 w-4" />
              </button>
            </div>
          )}
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="image/*" 
            className="hidden" 
          />
        </div>
      </div>
    </div>
  );
};

