export const generateThumbnailConcepts = async (topic: string, aspectRatio: string = "16:9", style: string, imageBase64: string | null = null): Promise<string> => {
  if (!topic.trim()) return "";

  const parts: any[] = [];

  if (imageBase64) {
    const base64Data = imageBase64.split(',')[1];
    parts.push({
      inlineData: {
        mimeType: 'image/jpeg',
        data: base64Data
      }
    });
    parts.push({
      text: `Create a professional YouTube thumbnail based on this reference image.
      Topic/Title to overlay: "${topic}"
      Style: ${style}
      Aspect Ratio: ${aspectRatio}

      Requirements:
      - Add the text "${topic}" in a bold, high-contrast font that is easy to read.
      - Ensure the text stands out against the background (use strokes or drop shadows if needed).
      - Maintain a professional, high-CTR look suitable for YouTube.
      - Keep the main subject of the original image visible if possible, or creatively blend it.
      `
    });
  } else {
    parts.push({
      text: `Create a professional YouTube thumbnail image.
      Topic/Title to overlay: "${topic}"
      Style: ${style}
      Aspect Ratio: ${aspectRatio}

      Requirements:
      - The image should visually represent the topic "${topic}".
      - Include the text "${topic}" clearly in the image using a bold, high-contrast font.
      - Use eye-catching colors and a layout optimized for high Click-Through Rate (CTR).
      - Ensure the text is large and readable on small screens.
      `
    });
  }

  try {
    // We use gemini-2.5-flash-image for image generation/editing
    const response = await ai.models.generateContent({
      model: imageModelId,
      contents: { parts: parts },
      config: {
        // Map UI aspect ratio to API supported values
        imageConfig: {
          aspectRatio: aspectRatio === '4:5' ? '4:3' : aspectRatio as any
        }
      },
    });

    // Iterate through parts to find the image
    const candidates = response.candidates;
    if (candidates && candidates.length > 0) {
      for (const part of candidates[0].content.parts) {
        if (part.inlineData) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    return ""; // No image found
  } catch (error: any) {
    console.error("Error in generateThumbnailConcepts:", error);
    throw new Error("Failed to generate thumbnail image. Please try again.");
  }
};

import React from 'react';
import { ArrowDownTrayIcon, PhotoIcon } from '@heroicons/react/24/outline';

interface ThumbnailOutputDisplayProps {
  content: string; // This will now be a base64 image string
  isLoading: boolean;
}

export const ThumbnailOutputDisplay: React.FC<ThumbnailOutputDisplayProps> = ({ content, isLoading }) => {

  const handleDownload = () => {
    if (!content) return;
    const link = document.createElement('a');
    link.href = content;
    link.download = `thumbnail-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (isLoading) {
    return (
        <div className="w-full h-full p-6 rounded-2xl glass-input flex items-center justify-center">
            <div className="text-center space-y-4">
              <div className="relative w-24 h-24 mx-auto">
                <div className="absolute inset-0 border-4 border-slate-200 dark:border-slate-700 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-green-500 rounded-full border-t-transparent animate-spin"></div>
              </div>
              <p className="text-slate-500 dark:text-slate-400 font-medium animate-pulse">Generating your thumbnail...</p>
            </div>
        </div>
    );
  }

  if (!content) {
      return (
        <div className="w-full h-full p-6 rounded-2xl glass-input flex flex-col items-center justify-center text-slate-400/70 dark:text-slate-500">
            <PhotoIcon className="h-16 w-16 mb-4 opacity-50" />
            <p className="italic">Your generated thumbnail will appear here.</p>
        </div>
      );
  }

  // Check if content is actually an image data URL
  const isImage = content.startsWith('data:image');

  if (!isImage) {
     return (
        <div className="w-full h-full p-6 rounded-2xl glass-input overflow-y-auto text-red-500">
           Error: Invalid image data received.
        </div>
     );
  }

  return (
    <div className="w-full h-full p-4 rounded-2xl glass-input flex flex-col">
      <div className="flex-grow flex items-center justify-center bg-slate-100 dark:bg-slate-900/50 rounded-xl overflow-hidden border border-slate-200 dark:border-slate-700 mb-4 shadow-inner relative group">
         <img 
           src={content} 
           alt="Generated Thumbnail" 
           className="max-w-full max-h-full object-contain shadow-lg"
         />
         <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors pointer-events-none"></div>
      </div>

      <button
        onClick={handleDownload}
        className="w-full py-3 bg-green-500 text-white rounded-xl font-bold shadow-lg shadow-green-500/30 hover:bg-green-600 active:scale-95 transition-all flex items-center justify-center gap-2"
      >
        <ArrowDownTrayIcon className="h-5 w-5" />
        Download Thumbnail
      </button>
