export const humanizeContent = async (text: string, tone: ToneType): Promise<string> => {
  if (!text.trim()) return "";

  const systemInstruction = `
    You are an expert writer and editor specializing in "humanizing" text. 
    Your goal is to take input text (which may be AI-generated or stiff) and rewrite it to sound natural, fluid, and human.

    Rules:
    1. Detect the language of the input text (e.g., English, Bengali, Spanish) and output in the SAME language.
    2. Remove robotic transitions (e.g., "In conclusion", "Furthermore", "Delving into").
    3. Vary sentence length and structure.
    4. Use idioms or natural phrasing appropriate for the requested tone.
    5. Keep the core meaning exactly the same, just change the delivery.
    6. Do not add conversational filler like "Here is your text" at the start. Just provide the rewritten text.
  `;

  const prompt = `
    Rewrite the following text to be more "${tone}" in tone. 
    Make it sound like a real human wrote it.

    Input Text:
    """
    ${text}
    """
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.8,
      },
    });

    return response.text || "Failed to generate text.";
  } catch (error: any) {
    console.error("Error in humanizeContent:", error);
    throw new Error("Failed to connect to Gemini API. Please check your connection or API key.");
  }
};

export const generateScript = async (
  topic: string, 
  format: ScriptFormat, 
  language: string, 
  style: ScriptStyle,
  platform: Platform,
  captionTone: CaptionTone,
  targetAudience: string,
  addEmojis: boolean
): Promise<string> => {
  if (!topic.trim()) return "";

  const systemInstruction = `
    You are an advanced Script Writer and Caption Generator AI.
    Always generate content strictly based on the user-selected parameters.

    OUTPUT FORMAT (Use Markdown Headers for sections):
    ### A. Script Intro
    (Strong hook, 1–2 lines)

    ### B. Main Script Body
    (Well-structured & engaging, suitable for ${format})

    ### C. Ending CTA
    (Clear Call to Action)

    ### D. Viral Caption
    (Optimized for ${platform}, ${captionTone} style)

    ### E. Short Description
    (SEO-optimized summary)

    ### F. SEO & Trending Hashtags
    (30 optimized tags)

    ### G. Relatable Topic Tags
    (20 relevant tags)

    RULES:
    - Target Audience: ${targetAudience || 'General Audience'}. If a specific category is selected, avoid general audience phrasing and speak directly to that niche.
    - Emojis: ${addEmojis ? 'ON (Use relevant emojis to enhance engagement)' : 'OFF (Do NOT use emojis)'}.
    - Language: ${language}.
    - Tone/Style: ${style}.
    - Keep formatting professional and concise. Do not add conversational filler before the output.
  `;

  const prompt = `
    Generate a professional video script and metadata based on:
    Topic: "${topic}"
    Content Type: ${format}
    Platform: ${platform}
    Language: ${language}
    Script Style: ${style}
    Caption Style: ${captionTone}
    Target Audience: ${targetAudience}
    Auto-Add Emojis: ${addEmojis}
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.9,
      },
    });

    return response.text || "Failed to generate script.";
  } catch (error: any) {
    console.error("Error in generateScript:", error);
    throw new Error("Failed to connect to Gemini API. Please check your connection or API key.");
  }
};

